type Id = number | string;
type Size = "small" | "medium" | "large";

function label(id: Id, size: Size): string {
  return `${id}-${size}`;
}

console.log(label(7, "small"));
console.log(label("x1", "large"));
console.log(label("x2", "huge"));

function pad(value: string | number): string {
  return value.padStart(4, "0");
}

function pad(value: string | number): string {
  if (typeof value === "number") {
    return String(value).padStart(4, "0");
  }
  return value.padStart(4, "0");
}

console.log(pad(7), pad("42"));

type Timestamps = { createdAt: string; updatedAt: string };
type Post = { title: string; body: string } & Timestamps;

const post: Post = {
  title: "Unions",
  body: "A value that can be one of several types.",
  createdAt: "2026-02-01",
  updatedAt: "2026-02-03",
};

type Handler = (event: string) => void;
const onSave: Handler = (event) => console.log(`saved after ${event}`);

onSave(post.title);

